const curriculum = JSON.parse(await readFile(curriculumPath, "utf8"));
const slotOrdinal = (slot) => Number(slot.slotId.match(/-(\d+)$/)?.[1] ?? 0);
const expectedBlocks = curriculum.blockPlans.filter((block) => block.nodeId === NODE);
const expectedMixByOperation = { decision_selection: "scenarioDecision", configuration_sequence: "configurationSequence", decision_diagnosis: "troubleshootingEffectiveState", tool_selection: "toolOrIacCommand", boundary_analysis: "boundaryOrContrast" };
const exactToolSourceByCard = new Map(Object.entries({
  "AZ104-N09-B01-15": "n09-metrics-cli",
  "AZ104-N09-B02-15": "n09-diagnostic-cli", "AZ104-N09-B02-16": "n09-dcr-cli",
  "AZ104-N09-B03-15": "n09-metrics-cli", "AZ104-N09-B03-16": "n09-metrics-cli",
  "AZ104-N09-B04-13": "n09-kql-where", "AZ104-N09-B04-14": "n09-kql-summarize", "AZ104-N09-B04-15": "n09-kql-join", "AZ104-N09-B04-16": "n09-kql-extend", "AZ104-N09-B04-17": "n09-kql-project", "AZ104-N09-B04-18": "n09-kql-render",
  "AZ104-N09-B05-17": "n09-alert-cli", "AZ104-N09-B05-18": "n09-action-cli",
  "AZ104-N09-B06-13": "n09-connection-cli", "AZ104-N09-B06-14": "n09-watcher-cli",
  "AZ104-N09-B07-15": "n09-backup-cli-vault",
  "AZ104-N09-B08-17": "n09-backup-recoverypoint-cli", "AZ104-N09-B08-18": "n09-backup-restore-cli",
  "AZ104-N09-B09-20": "n09-asr-cli", "AZ104-N09-B09-21": "n09-asr-cli",
}));
const seenPrompts = new Set();
const seenOptions = new Set();
const seenWrongTuples = new Set();
let totalCards = 0;
if (expectedBlocks.length !== 9 || Object.keys(blocks).length !== 9) throw new Error(`N09 block count mismatch: ${expectedBlocks.length}/${Object.keys(blocks).length}.`);
for (const block of expectedBlocks) {
  const cards = blocks[block.blockId];
  if (!cards || cards.length !== block.slotCount) throw new Error(`${block.blockId}: expected ${block.slotCount}, got ${cards?.length ?? 0}.`);
  const slots = curriculum.slots.filter((slot) => slot.blockId === block.blockId).sort((a, b) => slotOrdinal(a) - slotOrdinal(b));
  const actualMix = Object.fromEntries(Object.keys(block.questionMix).map((key) => [key, 0]));
  slots.forEach((slot, index) => {
    const card = cards[index];
    const spec = sourceById.get(card.source);
    if (!spec) throw new Error(`${block.blockId}-${index + 1}: unknown source ${card.source}.`);
    actualMix[expectedMixByOperation[slot.learningOperation]] += 1;
    const toolKey = `${block.blockId}-${index + 1}`;
    if (slot.learningOperation === "tool_selection" && exactToolSourceByCard.get(toolKey) !== card.source) throw new Error(`${toolKey}: tool source mismatch.`);
    if (!card.prompt || !card.correct || !card.reason || card.wrongs.length !== 3) throw new Error(`${toolKey}: incomplete card.`);
    if (seenPrompts.has(card.prompt)) throw new Error(`Duplicate prompt: ${card.prompt}`);
    seenPrompts.add(card.prompt);
    const options = [card.correct, ...card.wrongs.map((wrong) => wrong.text)];
    if (new Set(options).size !== 4) throw new Error(`${toolKey}: duplicate local option.`);
    for (const option of options) {
      if (seenOptions.has(option)) throw new Error(`${toolKey}: duplicate global option: ${option}`);
      seenOptions.add(option);
    }
    const tuple = card.wrongs.map((wrong) => wrong.text).join("\n");
    if (seenWrongTuples.has(tuple)) throw new Error(`${toolKey}: duplicate distractor tuple.`);
    seenWrongTuples.add(tuple);
    if (card.wrongs.some((wrong) => !wrong.text || !wrong.why || /all of the above|none of the above|obviously wrong|placeholder|temporary|future|draft|seed|baseline/i.test(`${wrong.text} ${wrong.why}`))) throw new Error(`${toolKey}: generic or incomplete distractor.`);
    const relevantText = `${card.prompt} ${card.correct} ${card.reason} ${card.wrongs.map((wrong) => `${wrong.text} ${wrong.why}`).join(" ")}`.toLowerCase();
    if (!spec.topics.some((topic) => relevantText.includes(topic.toLowerCase()))) throw new Error(`${toolKey}: source ${card.source} lacks topical relevance.`);
  });
  if (JSON.stringify(actualMix) !== JSON.stringify(block.questionMix)) throw new Error(`${block.blockId}: exact mix mismatch ${JSON.stringify(actualMix)}.`);
  totalCards += cards.length;
}
if (totalCards !== 172 || seenPrompts.size !== 172 || seenOptions.size !== 688 || seenWrongTuples.size !== 172) throw new Error(`N09 global uniqueness failed: ${totalCards}/${seenPrompts.size}/${seenOptions.size}/${seenWrongTuples.size}.`);

if (process.argv.includes("--check")) {
  console.log(`AZ104-N09 slot-order, exact-mix, topical-source, prompt, option, and explicit-distractor QA passed for ${totalCards} cases and ${seenOptions.size} globally unique options across ${expectedBlocks.length} blocks.`);
  process.exit(0);
}

const registrySources = sourceSpecs.map(({ boundary, transfer, topics, ...source }) => source);
const sourceRecords = new Map(curriculum.sourceRecords.map((source) => [source.sourceId, source]));
for (const source of registrySources) {
  const existing = sourceRecords.get(source.sourceId);
  sourceRecords.set(source.sourceId, existing ? { ...existing, ...source, authoritativeFor: [...new Set([...(existing.authoritativeFor ?? []), ...source.authoritativeFor])] } : source);
}
curriculum.sourceRecords = [...sourceRecords.values()].sort((a, b) => a.sourceId.localeCompare(b.sourceId));
for (const [blockId, cards] of Object.entries(blocks)) {
  const slots = curriculum.slots.filter((slot) => slot.blockId === blockId).sort((a, b) => slotOrdinal(a) - slotOrdinal(b));
  slots.forEach((slot, index) => {
    const requirement = slot.sourceRequirements.directFirstPartyDocumentation[0];
    requirement.testedProperties = [`${blockId.toLowerCase()}-${slot.learningOperation}-${String(index + 1).padStart(2, "0")}`];
    requirement.sourceRefs = [cards[index].source];
    requirement.resolutionState = "resolved_exact_direct";
  });
  const target = curriculum.targetPlans.find((entry) => entry.blockId === blockId);
  if (!target) throw new Error(`${blockId}: missing target plan.`);
  target.sourceRefs = [...new Set(cards.map((card) => card.source))].sort();
}
const activeSourceIds = new Set();
for (const slot of curriculum.slots) {
  for (const ref of slot.sourceRequirements.officialObjective?.sourceRefs ?? []) activeSourceIds.add(ref);
  for (const requirement of slot.sourceRequirements.directFirstPartyDocumentation ?? []) for (const ref of requirement.sourceRefs ?? []) activeSourceIds.add(ref);
}
const collectBlueprintSources = (value) => {
  if (Array.isArray(value)) return value.forEach(collectBlueprintSources);
  if (!value || typeof value !== "object") return;
  for (const [key, child] of Object.entries(value)) key === "sourceRefs" && Array.isArray(child) ? child.forEach((ref) => activeSourceIds.add(ref)) : collectBlueprintSources(child);
};
collectBlueprintSources(curriculum.examSimulationBlueprint);
curriculum.sourceRecords = curriculum.sourceRecords.filter((source) => activeSourceIds.has(source.sourceId));
const { promotionProvenance, contentFingerprint, ...fingerprintPayload } = curriculum;
curriculum.contentFingerprint = createHash("sha256").update(JSON.stringify(fingerprintPayload)).digest("hex");
await writeFile(curriculumPath, `${JSON.stringify(curriculum, null, 2)}\n`);

const anchorRegistry = JSON.parse(await readFile(anchorsPath, "utf8"));
const anchorSources = new Map(anchorRegistry.anchors.map((source) => [source.sourceId, source]));
for (const source of registrySources) {
  const existing = anchorSources.get(source.sourceId);
  anchorSources.set(source.sourceId, existing ? { ...existing, ...source, authoritativeFor: [...new Set([...(existing.authoritativeFor ?? []), ...source.authoritativeFor])] } : source);
}
const retainedSourceIds = new Set(curriculum.sourceRecords.map((source) => source.sourceId));
anchorRegistry.anchors = [...anchorSources.values()].filter((source) => retainedSourceIds.has(source.sourceId)).sort((a, b) => a.sourceId.localeCompare(b.sourceId));
await writeFile(anchorsPath, `${JSON.stringify(anchorRegistry, null, 2)}\n`);

const { manifest, model } = await buildManifest(ROOT);
const manifestTrack = manifest.tracks.find((entry) => entry.trackId === TRACK);
const canonicalTrack = model.curricula.get(TRACK);
const normalizedById = new Map(canonicalTrack.normalized.slots.map((slot) => [slot.slotId, slot]));
const optionIds = ["A", "B", "C", "D"];
for (const [blockId, cards] of Object.entries(blocks)) {
  const batchId = `az104-2026-08-16-${blockId}`;
  const provenance = { authoringMethod: "manual", approvalStatus: "unapproved", author: "Codex", createdAt: CREATED_AT, contentBatchId: batchId };
  const slots = manifestTrack.slots.filter((slot) => slot.learningBlockId === blockId).sort((a, b) => slotOrdinal(a) - slotOrdinal(b));
  const items = slots.map((slot, index) => {
    const card = cards[index];
    const normalized = normalizedById.get(slot.slotId);
    if (!slot.authoringAdmitted || !slot.sourceBinding || !slot.sourceBinding.sourceRefs.includes(card.source)) throw new Error(`${slot.slotId}: invalid source binding.`);
    const spec = sourceById.get(card.source);
    const raw = [{ text: card.correct, why: card.reason, correct: true }, ...card.wrongs.map((wrong) => ({ ...wrong, correct: false }))];
    const shift = index % 4;
    const arranged = [...raw.slice(shift), ...raw.slice(0, shift)];
    const answer = arranged.findIndex((option) => option.correct);
    return {
      itemId: `az104-${blockId}-${String(index + 1).padStart(3, "0")}`,
      slotId: slot.slotId, nodeId: NODE, learningBlockId: blockId,
      taxonomy: { examDomainId: normalized.raw.primarySimulationDomainId, competencyAreaId: NODE, topicId: blockId, skillAtomId: normalized.raw.directSkillOrDecisionAtomId },
      prompt: card.prompt,
      constraints: [spec.boundary, spec.transfer],
      interaction: { type: "choice", selectionMode: "single", options: arranged.map((option, i) => ({ optionId: optionIds[i], text: option.text })), acceptedOptionIds: [optionIds[answer]] },
      scoringContract: { type: "choice", resultSemantics: "exact_selected_set_with_partial_v1", selectionMode: "single" },
      feedback: { Reason: card.reason, Details: { mechanismOrProperty: card.reason, scenarioApplication: card.correct, errorCorrection: arranged.filter((option) => !option.correct).map((option) => option.why).join(" "), boundaryOrTradeoff: spec.boundary, transfer: spec.transfer, url: spec.url }, wrongOptionExplanationsByOptionId: Object.fromEntries(arranged.map((option, i) => [optionIds[i], option.why]).filter((_, i) => i !== answer)), omittedCorrectElementExplanationsByOptionId: {} },
      modeEligibility: slot.modeEligibility, sourceBinding: slot.sourceBinding, authoringProvenance: provenance,
    };
  });
  const payload = { schemaVersion: "certification-manual-source-v2", batchId, trackId: TRACK, familyId: "certification", contentVersion: "microsoft-azure-administrator-associate-az-104-authoring-v2026.08.15", taxonomyVersion: "2026.08.15", nodeId: NODE, learningBlockId: blockId, slotIds: items.map((item) => item.slotId), items, authoringProvenance: provenance };
  const output = join(ROOT, "manual/source", TRACK, NODE, `${blockId}.json`);
  await mkdir(join(output, ".."), { recursive: true });
  await writeFile(output, `${JSON.stringify(payload, null, 2)}\n`);
  console.log(`Authored ${items.length} reviewed items at ${output}.`);
}
